import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea, Select, SelectItem } from "@heroui/react";
import { FileUploader, Loading } from '../../components';
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";
import CreateSelect from "react-select/creatable";
import makeAnimated from "react-select/animated"
import { useDispatch, useSelector } from "react-redux";
import { resetRedux, uploadUserImages } from "../../redux/users/users/actions";
import { getLoggedInUser } from "../../helpers/authUtils";
import useApi from "../../hooks/useApi";
import categoriesApi from "../../api/categoriesApi";
import entitiesApi from "../../api/entitiesApi";
import { useNavigate } from "react-router-dom";
import paymentsApi from "../../api/paymentsApi";



export default function EntityCollectionAccountModal({ openCollectionAccountModal, setopenCollectionAccountModal, entity }) {
    const animatedComponent = makeAnimated();
    const loading = useSelector((state) => state.Users.loading);
    const response_code = useSelector((state) => state.Users.response_code);
    const response_message = useSelector((state) => state.Users.response_message);

    const [user, setUser] = useState()
    const dispatch = useDispatch()
    const [errors, setErrors] = useState([])
    useEffect(() => { setUser(getLoggedInUser()) }, [])



    const [psps, setpsps] = useState()
    //Retrieve plans

    const paymentServicesProvidersApi = useApi(paymentsApi.paymentsServicesProvidersAction)
    const getPaymentServicesProviders = async () => {
        await paymentServicesProvidersApi.request({
            "action": "GetAllPaymentServicesProviders"

        })
    }

    useEffect(() => {
        getPaymentServicesProviders()
    }, [])

    useEffect(() => {

        if (paymentServicesProvidersApi.data && paymentServicesProvidersApi.data.length) {

            setpsps(paymentServicesProvidersApi.data.map((i) => ({ label: i.psp_title, value: i.id })))
        }

    }, [paymentServicesProvidersApi.data])

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    useEffect(() => {
        if (response_message) {
            toast.success(response_message
            );
        }
    }, [response_message]);


    const formik = useFormik({
        initialValues: {

            psp: entity.psp ? { 'label': entity.psp.plan_title, 'value': entity.psp.psp } : { 'label': "Select psp", 'value': "" },

        },

        validationSchema: Yup.object({
            psp: Yup.string()

                .required("Plan is required"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)

            // resetForm();
        },
    });

    const handleSelectPSP=(value)=>{
        if(value.label==="JAMBOPAY"){
            getOrCreateJambopayUserProfile()
        }

        console.log("Value", value)
    }


    const getOrCreateJambopayUserProfile=()=>{
        
    }
    return (
        <>
            <Modal
                isOpen={openCollectionAccountModal}
                placement="center"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1 items-center">{entity.title}</ModalHeader>
                                <ModalBody className="items-center">Create collection Account</ModalBody>
                                <ModalBody>

                                    <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="psp"
                                            key="psp"
                                            name="psp"
                                            components={animatedComponent}
                                            placeholder="Select payment services provider"
                                            isClearable
                                            value={formik.values.psp}
                                            onChange={(value) => handleSelectPSP(value)}
                                            options={psps}
                                        />
                                        {formik.touched.psp && formik.errors.psp ? (
                                            <p className="text-red-400 text-sm">{formik.errors.psp}</p>
                                        ) : null}
                                    </div>




                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenCollectionAccountModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
