import React, { useCallback, useMemo, useState, useEffect } from "react";
import { useDropzone } from "react-dropzone";
import { useStateContext } from "../contexts/ContextProvider";

const baseStyle = {
  flex: 1,
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
  padding: "20px",
  borderWidth: 2,
  borderRadius: 2,
  borderColor: "#eeeeee",
  borderStyle: "dashed",
  backgroundColor: "#fafafa",
  color: "#bdbdbd",
  outline: "none",
  transition: "border .24s ease-in-out",
};

const focusedStyle = {
  borderColor: "#2196f3",
};

const acceptStyle = {
  borderColor: "#00e676",
};
// file['type'].split('/')[0] === 'image' ? URL.createObjectURL(file) : null
const rejectStyle = {
  borderColor: "#ff1744",
};
const FileUploader = ({ name, formik, types, value = [], accept, placeholder }) => {
  const [selectedImages, setSelectedImages] = useState(value);
  const { currentColor } = useStateContext();
  const [allImages, setAllImages] = useState(selectedImages);

  const onDrop = useCallback((acceptedFiles) => {
    acceptedFiles.map((file) =>
      Object.assign(file, {
        preview:
          file["type"].split("/")[0] === "image"
            ? URL.createObjectURL(file)
            : null,
      })
    );
    setSelectedImages(allImages.push(...acceptedFiles));
  }, []);
  const {
    getRootProps,
    getInputProps,
    isDragActive,
    isFocused,
    isDragAccept,
    isDragReject,
  } = useDropzone({
    onDrop,
    accept: { ...accept },
  });

  const style = useMemo(
    () => ({
      ...baseStyle,
      ...(isFocused ? focusedStyle : {}),
      ...(isDragAccept ? acceptStyle : {}),
      ...(isDragReject ? rejectStyle : {}),
    }),
    [isFocused, isDragAccept, isDragReject]
  );

  useEffect(() => {
    if (allImages && allImages.length) {
      let images = [];

      allImages.map((x) => {
        images.push(x);
      });

      formik.setFieldValue(`${name}`, images);
    }
  }, [allImages, selectedImages]);

  return (
    <div>
      <div {...getRootProps({ style })}>
        <input
          className="border-gray-400 rounded-md w-full"
          style={{

            borderStyle: "dotted",
            borderRadius: "10px",
          }}
          {...getInputProps()}
        />

        {isDragActive ? (
          <p>Drop the files here ...</p>
        ) : (
          <p className="text-gray-500">{placeholder}</p>
        )}
      </div>
      {/* {selected_images} */}
    </div>
  );
};

export default FileUploader;
